"use client";

import { Button } from "../atoms/button";
import { cn } from "../lib/cn";
import { Sheet } from "../molecules/sheet";
import {
  createContext,
  useCallback,
  useContext,
  useEffect,
  useId,
  useState,
  type ButtonHTMLAttributes,
  type HTMLAttributes,
  type ReactNode,
} from "react";

const DESKTOP_MQ = "(min-width: 900px)";

export type AppShellProps = HTMLAttributes<HTMLDivElement> & {
  /** Sticky top chrome (usually glass). */
  header?: ReactNode;
  /** Sidebar content — desktop rail + mobile Sheet body. */
  sidebar?: ReactNode;
  children?: ReactNode;
  /** Controlled desktop collapse (icon rail). Desktop only. */
  collapsed?: boolean;
  defaultCollapsed?: boolean;
  onCollapsedChange?: (collapsed: boolean) => void;
  /** Controlled mobile navigation drawer. */
  mobileNavOpen?: boolean;
  defaultMobileNavOpen?: boolean;
  onMobileNavOpenChange?: (open: boolean) => void;
  /** Title for the mobile Sheet. */
  mobileNavTitle?: ReactNode;
};

type AppShellContextValue = {
  collapsed: boolean;
  setCollapsed: (next: boolean) => void;
  toggleCollapsed: () => void;
  mobileNavOpen: boolean;
  setMobileNavOpen: (next: boolean) => void;
  toggleMobileNav: () => void;
  isDesktop: boolean;
  /** False until matchMedia has run on the client (avoids SSR/hydration split). */
  layoutReady: boolean;
  hasSidebar: boolean;
};

const AppShellContext = createContext<AppShellContextValue | null>(null);

/** Access AppShell collapse / mobile nav state from chrome controls. */
export function useAppShell(): AppShellContextValue {
  const ctx = useContext(AppShellContext);
  if (!ctx) {
    throw new Error("useAppShell must be used within AppShell");
  }
  return ctx;
}

/**
 * Desktop breakpoint via matchMedia.
 * SSR + first client paint: layoutReady=false so we do not mount rail vs Sheet
 * until after hydration (avoids Next.js structural mismatch on mobile).
 */
function useDesktopMedia(): { isDesktop: boolean; layoutReady: boolean } {
  const [isDesktop, setIsDesktop] = useState(false);
  const [layoutReady, setLayoutReady] = useState(false);

  useEffect(() => {
    const mq = window.matchMedia(DESKTOP_MQ);
    const sync = () => setIsDesktop(mq.matches);
    sync();
    setLayoutReady(true);
    mq.addEventListener("change", sync);
    return () => mq.removeEventListener("change", sync);
  }, []);

  return { isDesktop, layoutReady };
}

/**
 * Organism — AppShell
 * Responsive layout: header + optional sidebar + main.
 * Desktop: collapsible sticky rail. Mobile: same sidebar slot in a left Sheet.
 */
export function AppShell({
  className,
  header,
  sidebar,
  children,
  collapsed: collapsedProp,
  defaultCollapsed = false,
  onCollapsedChange,
  mobileNavOpen: mobileOpenProp,
  defaultMobileNavOpen = false,
  onMobileNavOpenChange,
  mobileNavTitle = "Navigation",
  ...props
}: AppShellProps) {
  const { isDesktop, layoutReady } = useDesktopMedia();
  const hasSidebar = sidebar != null;

  const [collapsedUncontrolled, setCollapsedUncontrolled] =
    useState(defaultCollapsed);
  const collapsed = collapsedProp ?? collapsedUncontrolled;

  const setCollapsed = useCallback(
    (next: boolean) => {
      if (collapsedProp === undefined) setCollapsedUncontrolled(next);
      onCollapsedChange?.(next);
    },
    [collapsedProp, onCollapsedChange],
  );

  const toggleCollapsed = useCallback(() => {
    setCollapsed(!collapsed);
  }, [collapsed, setCollapsed]);

  const [mobileUncontrolled, setMobileUncontrolled] = useState(
    defaultMobileNavOpen,
  );
  const mobileNavOpen = mobileOpenProp ?? mobileUncontrolled;

  const setMobileNavOpen = useCallback(
    (next: boolean) => {
      if (mobileOpenProp === undefined) setMobileUncontrolled(next);
      onMobileNavOpenChange?.(next);
    },
    [mobileOpenProp, onMobileNavOpenChange],
  );

  const toggleMobileNav = useCallback(() => {
    setMobileNavOpen(!mobileNavOpen);
  }, [mobileNavOpen, setMobileNavOpen]);

  // Leave mobile drawer when crossing to desktop.
  useEffect(() => {
    if (isDesktop && mobileNavOpen) setMobileNavOpen(false);
  }, [isDesktop, mobileNavOpen, setMobileNavOpen]);

  const ctx: AppShellContextValue = {
    collapsed,
    setCollapsed,
    toggleCollapsed,
    mobileNavOpen,
    setMobileNavOpen,
    toggleMobileNav,
    isDesktop,
    layoutReady,
    hasSidebar,
  };

  // Only mount rail/Sheet after client media query — SSR + first paint match.
  const showDesktopRail = hasSidebar && layoutReady && isDesktop;
  const showMobileSheet = hasSidebar && layoutReady && !isDesktop;

  return (
    <AppShellContext.Provider value={ctx}>
      <div
        className={cn(
          "sg-shell",
          hasSidebar && "sg-shell-with-sidebar",
          className,
        )}
        data-collapsed={hasSidebar && collapsed ? "true" : undefined}
        data-layout-ready={layoutReady ? "true" : undefined}
        {...props}
      >
        {showDesktopRail ? (
          <aside
            className={cn("sg-shell-sidebar", "sg-surface-glass")}
            data-collapsed={collapsed ? "true" : undefined}
          >
            {sidebar}
          </aside>
        ) : null}

        {header ? (
          <header className="sg-shell-header">
            <div className={cn("sg-shell-header-inner", "sg-surface-glass")}>
              {header}
            </div>
          </header>
        ) : null}

        <main className="sg-shell-main">
          <div className="sg-shell-main-inner">{children}</div>
        </main>
      </div>

      {showMobileSheet ? (
        <Sheet
          open={mobileNavOpen}
          onOpenChange={setMobileNavOpen}
          title={mobileNavTitle}
          side="left"
          panelClassName="sg-shell-mobile-panel"
        >
          <div className="sg-shell-mobile-nav">{sidebar}</div>
        </Sheet>
      ) : null}
    </AppShellContext.Provider>
  );
}

export type AppShellMenuButtonProps = ButtonHTMLAttributes<HTMLButtonElement> & {
  /** Accessible name. Default "Open navigation". */
  label?: string;
};

/** Header control — opens the mobile sidebar Sheet (hidden on desktop). */
export function AppShellMenuButton({
  className,
  label = "Open navigation",
  type = "button",
  onClick,
  ...props
}: AppShellMenuButtonProps) {
  const { toggleMobileNav, isDesktop, layoutReady, hasSidebar, mobileNavOpen } =
    useAppShell();

  if (!hasSidebar || !layoutReady || isDesktop) return null;

  return (
    <Button
      type={type}
      variant="ghost"
      size="sm"
      iconOnly
      className={cn("sg-shell-menu-btn", className)}
      aria-label={label}
      aria-expanded={mobileNavOpen}
      {...props}
      onClick={(e) => {
        onClick?.(e);
        if (!e.defaultPrevented) toggleMobileNav();
      }}
    >
      <span className="sg-shell-menu-icon" aria-hidden="true">
        <span />
        <span />
        <span />
      </span>
    </Button>
  );
}

export type AppShellCollapseButtonProps =
  ButtonHTMLAttributes<HTMLButtonElement> & {
    /** Accessible name when expanded. */
    collapseLabel?: string;
    /** Accessible name when collapsed. */
    expandLabel?: string;
  };

/** Sidebar control — toggles desktop icon rail (hidden on mobile). */
export function AppShellCollapseButton({
  className,
  collapseLabel = "Collapse sidebar",
  expandLabel = "Expand sidebar",
  type = "button",
  onClick,
  ...props
}: AppShellCollapseButtonProps) {
  const { collapsed, toggleCollapsed, isDesktop, layoutReady, hasSidebar } =
    useAppShell();

  if (!hasSidebar || !layoutReady || !isDesktop) return null;

  return (
    <Button
      type={type}
      variant="ghost"
      size="sm"
      iconOnly
      className={cn("sg-shell-collapse-btn", className)}
      aria-label={collapsed ? expandLabel : collapseLabel}
      aria-pressed={collapsed}
      {...props}
      onClick={(e) => {
        onClick?.(e);
        if (!e.defaultPrevented) toggleCollapsed();
      }}
    >
      <span className="sg-shell-collapse-icon" aria-hidden="true">
        {collapsed ? "»" : "«"}
      </span>
    </Button>
  );
}

export type ShellNavItemProps = HTMLAttributes<HTMLAnchorElement> & {
  href?: string;
  active?: boolean;
  /** Leading mark — preferred when the shell is collapsed. */
  icon?: ReactNode;
  children?: ReactNode;
};

export function ShellNav({
  className,
  children,
  ...props
}: HTMLAttributes<HTMLElement>) {
  return (
    <nav className={cn("sg-shell-nav", className)} {...props}>
      {children}
    </nav>
  );
}

export function ShellNavItem({
  className,
  href = "#",
  active = false,
  icon,
  children,
  ...props
}: ShellNavItemProps) {
  const glyphId = useId();
  const labelText =
    typeof children === "string" || typeof children === "number"
      ? String(children)
      : undefined;
  const glyph = labelText?.trim().charAt(0) || "·";

  return (
    <a
      href={href}
      className={cn("sg-shell-nav-item", className)}
      data-active={active || undefined}
      aria-current={active ? "page" : undefined}
      {...props}
    >
      {icon ? (
        <span className="sg-shell-nav-icon" aria-hidden="true">
          {icon}
        </span>
      ) : (
        <span
          className="sg-shell-nav-glyph"
          aria-hidden="true"
          data-for={glyphId}
        >
          {glyph}
        </span>
      )}
      <span className="sg-shell-nav-label" id={glyphId}>
        {children}
      </span>
    </a>
  );
}

/** Values allowed in `cn(...)` — only strings survive. */
// eslint-disable-next-line @typescript-eslint/no-explicit-any
type ClassValue = string | false | null | undefined | 0 | 0n | boolean;

/**
 * Tiny class merger — no runtime deps.
 * Prefer this over pulling tailwind-merge until we need conflict resolution.
 */
export function cn(...parts: ClassValue[]): string {
  return parts.filter((part): part is string => typeof part === "string" && part.length > 0).join(" ");
}

/** Shared visual “look” languages across controls. */

export type ButtonLook = "solid" | "soft" | "glass" | "gradient" | "neon";

export type RadioLook = "dot" | "card" | "chip";

export type CheckboxLook = "box" | "card" | "pill";

export type SwitchLook = "track" | "ios" | "minimal";

export type BadgeLook = "soft" | "solid" | "outline" | "glow";

export type FieldLook = "solid" | "underline" | "filled" | "ghost";

export type SelectLook = "solid" | "soft" | "glass" | "gradient";

export type TabsLook = "pill" | "underline" | "segmented";

export type AvatarLook = "circle" | "rounded" | "soft";

export type TooltipLook = "frost" | "solid" | "accent";

export type CardLook = "flat" | "raised" | "outline" | "glow";

/** NumberInput shell + stepper language */
export type NumberInputLook = "soft" | "solid" | "outline" | "ghost";

/** Slider track / thumb language */
export type SliderLook = "soft" | "solid" | "glass" | "accent";

/** FileField trigger surface */
export type FileFieldLook = "solid" | "soft" | "dashed" | "ghost";

/** Progress track / fill language */
export type ProgressLook = "soft" | "solid" | "glass" | "accent" | "striped";

/** StatusDot chrome language (color still from status / color) */
export type StatusDotLook = "soft" | "solid" | "outline" | "glow";

/** Chip surface language */
export type ChipLook = "soft" | "solid" | "outline" | "glass" | "glow";

/** CloseButton chrome */
export type CloseButtonLook = "ghost" | "soft" | "solid" | "danger";

/**
 * Collapsible / Accordion disclosure surface
 * soft = frost card · solid = long content · glass = chrome · outline = border only · ghost = flush list
 */
export type CollapsibleLook = "soft" | "solid" | "glass" | "outline" | "ghost";

export type AccordionLook = CollapsibleLook;

/** Breadcrumb chrome: plain path · soft tray · pill chips */
export type BreadcrumbLook = "plain" | "soft" | "pill";

/** Pagination control chrome */
export type PaginationLook = "soft" | "solid" | "ghost" | "glass";

/** EmptyState surface */
export type EmptyStateLook = "solid" | "soft" | "outline";

/**
 * Stepper language
 * soft = frost track · solid = solid rail · outline = line only
 * dots = progress line + large dots · pills = segmented chip row
 */
export type StepperLook = "soft" | "solid" | "outline" | "dots" | "pills";

/**
 * Toolbar strip
 * soft | solid | glass | ghost | accent (accent edge rail)
 */
export type ToolbarLook = "soft" | "solid" | "glass" | "ghost" | "accent";

/** List host surface */
export type ListLook = "soft" | "solid" | "outline" | "ghost" | "inset";

/**
 * Stat metric tile
 * solid | soft | glass | outline | accent (left rail)
 */
export type StatLook = "solid" | "soft" | "glass" | "outline" | "accent";

/** PageHeader chrome: plain flush · soft frost · solid panel · glass chrome */
export type PageHeaderLook = "plain" | "soft" | "solid" | "glass";

/** SettingsSection panel chrome */
export type SettingsSectionLook = "soft" | "solid" | "glass" | "plain";

/**
 * DataTable surface language
 * soft = frost · solid = panel · glass = chrome · outline = border · ghost = flush
 */
export type DataTableLook = "soft" | "solid" | "glass" | "outline" | "ghost";

/**
 * Motion recipes — component-specific animation menus.
 * Parallel to `look` (visual surface). Always pair with `prefers-reduced-motion`.
 *
 * Defaults match the pre-motion global micro-interactions so existing UIs
 * keep the same feel when no prop is passed.
 */

/** Shared “off” token used on every control. */
export type MotionNone = "none";

export type ButtonMotion = MotionNone | "lift" | "press" | "sheen" | "ripple";

export type CheckboxMotion = MotionNone | "pop" | "draw" | "fade-in" | "bounce";

export type RadioMotion = MotionNone | "pop" | "dot-scale" | "ring-expand";

export type SwitchMotion = MotionNone | "snap" | "spring" | "elastic";

export type FieldMotion = MotionNone | "ring" | "underline-grow" | "glow";

export type SelectMotion = MotionNone | "fade" | "scale" | "slide-down";

export type TooltipMotion = MotionNone | "fade" | "scale" | "slide";

export type BadgeMotion = MotionNone | "pulse" | "pop-in" | "shimmer";

export type AvatarMotion = MotionNone | "lift" | "ring-pulse" | "status-ping";

/**
 * Tabs indicator + content enter.
 * - none: instant active swap
 * - fade: soft cross-fade on active chrome / content
 * - slide: moving pill or underline indicator (content still fades)
 */
export type TabsMotion = MotionNone | "fade" | "slide";

export type ModalMotion = MotionNone | "scale" | "fade" | "slide-up";

export type ToastMotion = MotionNone | "slide-in" | "pop";

export type CardMotion = MotionNone | "lift" | "glow-pulse";

/** Popover / DropdownMenu panel enter (same recipe set as Select menu). */
export type PopoverMotion = MotionNone | "fade" | "scale" | "slide-down";

export type DropdownMenuMotion = MotionNone | "fade" | "scale" | "slide-down";

/** ContextMenu panel — same recipes as DropdownMenu / Popover. */
export type ContextMenuMotion = MotionNone | "fade" | "scale" | "slide-down";

/** DatePicker calendar panel — same recipes as Select. */
export type DatePickerMotion = MotionNone | "fade" | "scale" | "slide-down";

/** Collapsible / Accordion panel open motion. */
export type CollapsibleMotion = MotionNone | "fade" | "height";

export type AccordionMotion = CollapsibleMotion;

/** Sheet edge panel enter/exit. */
export type SheetMotion = MotionNone | "slide" | "fade";

/** HoverCard panel (Popover family). */
export type HoverCardMotion = MotionNone | "fade" | "scale" | "slide-down";

/** Defaults — preserve current product feel. */
export const MOTION_DEFAULTS = {
  button: "lift",
  checkbox: "pop",
  radio: "pop",
  switch: "spring",
  field: "ring",
  select: "scale",
  tooltip: "scale",
  badge: "none",
  avatar: "lift",
  tabs: "slide",
  modal: "scale",
  toast: "slide-in",
  card: "lift",
  popover: "scale",
  dropdownMenu: "scale",
  contextMenu: "scale",
  datePicker: "scale",
  collapsible: "height",
  accordion: "height",
  sheet: "slide",
  hoverCard: "scale",
} as const satisfies Record<string, string>;
